const descriptions={all:'Explore natural pearl, agate and geode — the starting points for our one-of-a-kind necklaces.',necklace:'One handmade necklace at a time. Each piece is designed around its stones and never repeated.',bracelet:'The next chapter: bracelets. New pieces will appear here when they are ready.',pearl:'Pearl — soft lustre, irregular silhouettes. No two pearls catch the light in quite the same way.',agate:'Agate — translucent layers and earthy colour. We let each stone’s natural pattern guide the piece.',geode:'Geode — a quiet exterior, a crystalline world within. Each natural formation brings its own character.'};
document.querySelectorAll('[data-collection]').forEach(control=>control.addEventListener('click',()=>{const selected=control.dataset.collection;document.getElementById('collection-description').textContent=descriptions[selected];document.getElementById('collection-gallery').hidden=selected==='bracelet';document.querySelectorAll('.collection-tabs button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.collection===selected)));}));
